// muuri.js assumes that Function.prototype.bind exists,
// but that's not available in wkhtmltopdf
// see https://github.com/wkhtmltopdf/wkhtmltopdf/issues/3796

Function.prototype.bind = Function.prototype.bind || function (thisArg /* , arg1, ..., argN */) {
    var func = this;
    var firstArgs = Array.prototype.slice.call(arguments, 1);
    return function () {
        var secondArgs = Array.prototype.slice.call(arguments);
        return func.apply(thisArg, firstArgs.concat(secondArgs));
    };
};


