  /**
   * Tillg�nglighetsfunktion
   * Initierar sk�rml�saruppl�sning f�r urval/picklists.
   *
   * - L�ser upp aktivt val via aria-activedescendant
   * 
   * - L�ser �ven om valet �r markerat (class="selected" p� <tr>)
   * 
   *
   * F�ruts�ttning:
   * - aria-activedescendant finns (Search aktiverad, men kan d�ljas visuellt)
   */

  _initPicklistScreenReaderSupport: function () {

    /* -------------------------
        Announcer (aria-live)
        ------------------------- */
    let announcer = document.getElementById("sr-announce");
    if (!announcer) {
      announcer = document.createElement("div");
      announcer.id = "sr-announce";
      announcer.style.position = "absolute";
      announcer.style.left = "-9999px";
      announcer.style.width = "1px";
      announcer.style.height = "1px";
      announcer.style.overflow = "hidden";
      document.body.appendChild(announcer);
    }
    announcer.setAttribute("role", "alert");

    function say(text) {
      const msg = String(text || "").trim();
      if (!msg) return;
      announcer.textContent = "";
      requestAnimationFrame(() => {
        announcer.textContent = msg;
      });
    }


    // Hitta n�rmaste container som inneh�ller tabellen
    function findWidgetContainer(host) {
      let n = host;
      while (n && n !== document.body) {
        if (n.querySelector && n.querySelector("table tbody tr td")) {
          return n;
        }
        n = n.parentElement;
      }
      return null;
    }

    // Sl� upp target inom r�tt container (hanterar duplicate ids)
    function findTargetInContainer(container, id) {
      if (!container) return null;

      const matches = container.querySelectorAll(`[id="${id}"]`);
      if (!matches.length) return null;

      // F�redra element i tabell
      const inTable = Array.from(matches).find(el =>
        el.closest && el.closest("table")
      );

      return inTable || matches[0];
    }

    /* -------------------------
        Observer f�r aria-activedescendant
        ------------------------- */
    const observer = new MutationObserver((mutations) => {
      for (const m of mutations) {
        const host = m.target;
        if (!(host instanceof HTMLElement)) continue;

        const id = host.getAttribute("aria-activedescendant");
        if (!id) continue;

        const container = findWidgetContainer(host);
        if (!container) continue;

        const target = findTargetInContainer(container, id);
        if (!target) continue;

        const baseText = (target.innerText || target.textContent || "").trim();
        if (!baseText) continue;

        // Markerad?
        const row = target.closest("tr");
        const isSelected = !!row && row.classList.contains("selected");

        const spokenText = isSelected
          ? `${baseText}, markerad`
          : `${baseText}, inte markerad`;

        say(spokenText);
      }
    });

    observer.observe(document.body, {
      subtree: true,
      attributes: true,
      attributeFilter: ["aria-activedescendant"]
    });

    /* -------------------------
        St�da felaktig ARIA p� wrappers
        ------------------------- */

    console.log("? Picklist screen reader support initierad");
  },



_tableNotTabable: function () {

    function fixTable() {
        var tables = document.querySelectorAll("table.dvp_table_table");

        tables.forEach(function (table) {
            table.setAttribute("aria-hidden", "true");
            table.tabIndex = -1;
        });
    }

    fixTable();

    new MutationObserver(function () {
        fixTable();
    }).observe(document.body, {
        childList: true,
        subtree: true
    });
},

